<div data-inventory-devices><div class="portal-card-head"><div><strong>Serialized cihazlar</strong><small>Asset kodu, serial, MAC, model, veziyyet ve cari lokasiya.</small></div></div><form class="inventory-filter" method="get" action="operations-center.php" data-inventory-filter><input type="hidden" name="section" value="inventory"><input type="hidden" name="inventory_tab" value="devices"><div class="portal-form-row"><label>Axtaris</label><input type="search" name="search" value="<?= e((string) ($query['search'] ?? '')); ?>" placeholder="Asset, serial, MAC, model"></div><div class="portal-form-row"><label>Veziyyet</label><input type="text" name="condition" value="<?= e((string) ($query['condition'] ?? '')); ?>" placeholder="Condition"></div><span></span><button class="portal-primary-btn" type="submit">Tetbiq et</button></form><div class="portal-table-wrap"><table class="portal-table"><thead><tr><th>Asset</th><th>Mehsul / model</th><th>Serial</th><th>MAC</th><th>Lifecycle</th><th>Veziyyet</th><th>Lokasiya</th><th>Tarixce</th></tr></thead><tbody><?php foreach ($rows as $row): ?><tr data-inventory-row><td><strong><?= e((string) ($row['asset_code'] ?? '-')); ?></strong><br><small><?= e((string) ($row['ownership_type'] ?? '-')); ?></small></td><td><?= e(trim((string) (($row['vendor'] ?? '') . ' ' . ($row['model'] ?? ''))) ?: (string) ($row['item_name'] ?? '-')); ?></td><td><?= e((string) ($row['serial_number'] ?? '-')); ?></td><td><?= e((string) ($row['mac_address'] ?? '-')); ?></td><td><?= e((string) ($row['lifecycle_status'] ?? '-')); ?></td><td><?= e((string) ($row['condition_status'] ?? '-')); ?></td><td><?= e((string) ($row['current_location_type'] ?? '-')); ?> / <?= e((string) ($row['current_location_id'] ?? '-')); ?></td><td>I:<?= e((string) ($row['installation_count'] ?? 0)); ?> F:<?= e((string) ($row['failure_count'] ?? 0)); ?> R:<?= e((string) ($row['return_count'] ?? 0)); ?></td></tr><?php endforeach; ?><?php if ($rows === []): ?><tr><td colspan="8" class="in